    x.addEventListener('click',function(e){e.stopPropagation();var c=card.querySelector('.rv-weather-close');if(c)c.click();});   // dùng lại nút đóng của widget cũ
    card.insertBefore(wrap,card.firstChild);card.appendChild(x);
    var glass=document.createElement('div');glass.className='rv-neon-glass';card.parentNode.insertBefore(glass,card);   // lớp kính mờ nằm sau bảng (phải ở phía trang chính mới thấy được ảnh nền để làm mờ)
    var o={card:card,glass:glass,frame:wrap.querySelector('iframe'),nw:nw,fh:nw>1000?760:570,loaded:false};
    function collapse(){if(!host.classList.contains('rv-weather-open'))return;var c=card.querySelector('.rv-weather-close');if(c)c.click();}   // nhấn vào bất kỳ chỗ nào của bảng đang mở -> thu lại (như nút mũi tên)
    card.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('.rv-neon-x'))return;collapse();});
